<script lang="ts">
  import type {AppData,Row} from '#lib/client/types.ts';import {display,displayTimestamp} from '#lib/client/api.ts';
  let {snapshot={},data}:{snapshot?:Row;data:AppData}=$props();
  const intervals=$derived([...(snapshot.segments||snapshot.allocations||[])].sort((a,b)=>Date.parse(a.started_at||a.start_at)-Date.parse(b.started_at||b.start_at)));
  function order(interval:Row){if(interval.kind==='break')return '—';if(interval.order_id)return display(interval.order_id,'order_id',data);const matches=(snapshot.allocations||[]).filter((a:Row)=>a.time_segment_id===interval.id||Date.parse(a.started_at)<Date.parse(interval.ended_at||interval.end_at)&&Date.parse(a.ended_at)>Date.parse(interval.started_at||interval.start_at));const ids=[...new Set(matches.map((a:Row)=>a.order_id))];return ids.length===1?display(ids[0],'order_id',data):ids.length>1?'Mehrere Zuordnungen':'—';}
</script>
<div class="time-snapshot">
  {#if snapshot.session}<dl><div><dt>Beginn</dt><dd>{displayTimestamp(snapshot.session.started_at)}</dd></div><div><dt>Ende</dt><dd>{displayTimestamp(snapshot.session.ended_at)}</dd></div></dl>{/if}
  {#if intervals.length}<div class="table-scroll"><table class="data-table"><thead><tr><th>Art</th><th>Beginn</th><th>Ende</th><th>Auftrag</th></tr></thead><tbody>{#each intervals as interval}<tr><td>{interval.kind==='break'?'Pause':'Arbeit'}</td><td>{displayTimestamp(interval.started_at||interval.start_at)}</td><td>{displayTimestamp(interval.ended_at||interval.end_at)}</td><td>{order(interval)}</td></tr>{/each}</tbody></table></div>{:else}<p class="small">Für diesen Stand liegen keine bestätigten Intervalle vor.{snapshot.conflicts?.length?` ${snapshot.conflicts.length} Originalaufzeichnung(en) sind als Konfliktnachweis erhalten.`:''}</p>{/if}
<div class="mt">{#if snapshot.allocations?.length}<h3 style="font-size:13px;font-weight:500;margin-bottom:12px">Tatsächliche Arbeitszuordnung</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Von</th><th>Bis</th><th>Auftrag</th><th>Tätigkeit</th></tr></thead><tbody>{#each [...snapshot.allocations].sort((a,b)=>Date.parse(a.started_at)-Date.parse(b.started_at)) as allocation}<tr><td>{displayTimestamp(allocation.started_at)}</td><td>{displayTimestamp(allocation.ended_at)}</td><td>{display(allocation.order_id,'order_id',data)}</td><td>{allocation.activity?display(allocation.activity,'activity'):'Nicht angegeben'}</td></tr>{/each}</tbody></table></div>{/if}</div>
  <details class="mt"><summary class="field-help">Vollständigen Nachweis ansehen</summary><pre class="json-preview mt">{JSON.stringify(snapshot,null,2)}</pre></details>
</div>
<style>.time-snapshot{border:1px solid var(--line);border-radius:10px;padding:17px;min-width:0}.time-snapshot dl{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:0 0 18px}dt{font-size:12px;color:var(--muted);margin-bottom:5px}dd{font-size:14px;margin:0}.time-snapshot summary{cursor:pointer}</style>
